var voices=audio.GetComponentsInChildren<AudioSource>(true);int count=voices.Length;int phase=0,frame=Time.frameCount,before=audio.PlayedCues,feelBefore=0;float began=Time.realtimeSinceStartup;int oldMusic=audio.MusicSource.GetInstanceID();int oldUI=ui.GetInstanceID();var rock=UnityEngine.Object.FindObjectsByType<Bulldozer.Player.MineableRock>(FindObjectsSortMode.None).First(r=>r.naturalBoulder&&!r.Depleted);
